impl TeacherGpuCallExecution {
    fn teacher_run_id(&self) -> &str {
        match self {
            Self::Started { teacher_run_id, .. } | Self::NotStarted { teacher_run_id, .. } => {
                teacher_run_id
            }
        }
    }

    fn started(&self) -> bool {
        matches!(self, Self::Started { .. })
    }
}

